/// A [Glyph] at [size], in [color] or the surrounding icon colour. With
/// [tinted] off only the strokes and dots are drawn.
class GlyphIcon extends StatelessWidget {
  const GlyphIcon(
    this.glyph, {
    super.key,
    this.size = 22,
    this.color,
    this.weight = 1.6,
    this.tinted = true,
  });

  final Glyph glyph;
  final double size;
  final Color? color;

  /// Stroke width in logical pixels.
  final double weight;
  final bool tinted;

  @override
  Widget build(BuildContext context) {
    final ink = color ?? IconTheme.of(context).color ?? Hue.ink;
    // Like Icon, keep the drawn size when the parent asks for more room.
    return Center(
      widthFactor: 1,
      heightFactor: 1,
      child: SizedBox.square(
        dimension: size,
        child: CustomPaint(
          painter: GlyphPainter(glyph, ink, weight, tinted: tinted),
        ),
      ),
    );
  }
}

class GlyphPainter extends CustomPainter {
  const GlyphPainter(this.glyph, this.color, this.weight, {this.tinted = true});

  final Glyph glyph;
  final Color color;
  final double weight;
  final bool tinted;

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.shortestSide / 24;
    if (scale <= 0) return;
    final (tint, line, solid) = _paths[glyph] ??= _build(glyph);
    canvas
      ..save()
      ..translate((size.width - 24 * scale) / 2, (size.height - 24 * scale) / 2)
      ..scale(scale);
    if (tinted) {
      canvas.drawPath(tint, Paint()..color = color.withValues(alpha: 0.28));
    }
    canvas
      ..drawPath(
        line,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = weight / scale
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round
          ..color = color,
      )
      ..drawPath(solid, Paint()..color = color)
      ..restore();
  }

  @override
  bool shouldRepaint(GlyphPainter old) =>
      old.glyph != glyph ||
      old.color != color ||
      old.weight != weight ||
      old.tinted != tinted;
}

/// Each glyph's paths, built once on the 24-unit grid and reused by every
/// icon that shows it.
final _paths = <Glyph, (Path, Path, Path)>{};

(Path, Path, Path) _build(Glyph glyph) {
  final tint = Path();
  final line = Path();
  final solid = Path();
  _draw(glyph, tint, line, solid);
  return (tint, line, solid);
}

void _poly(Path p, List<double> xy, {bool close = false}) {
  p.moveTo(xy[0], xy[1]);
  for (var i = 2; i < xy.length; i += 2) {
    p.lineTo(xy[i], xy[i + 1]);
  }
  if (close) p.close();
}

void _box(Path p, double l, double t, double r, double b, double radius) {
  p.addRRect(RRect.fromLTRBR(l, t, r, b, Radius.circular(radius)));
}

void _ring(Path p, double x, double y, double r) {
  p.addOval(Rect.fromCircle(center: Offset(x, y), radius: r));
}

void _arc(Path p, double x, double y, double r, double from, double sweep) {
  p.addArc(
    Rect.fromCircle(center: Offset(x, y), radius: r),
    from * pi / 180,
    sweep * pi / 180,
  );
}

void _arcTo(Path p, double x, double y, double r, double from, double sweep) {
  p.arcTo(
    Rect.fromCircle(center: Offset(x, y), radius: r),
    from * pi / 180,
    sweep * pi / 180,
    false,
  );
}

final _svgToken = RegExp(r'[MmLlHhVvCcSsAaZz]|-?(?:\d*\.\d+|\d+\.?\d*)');

bool _svgCommand(String token) => token.length == 1 && RegExp(r'[A-Za-z]').hasMatch(token);

/// Adds the outline of SVG path data [d] to [p]: the commands M L H V C S
/// A Z, each in absolute or relative form, on the 24-unit grid.
void _svg(Path p, String d) {
  final t = [for (final m in _svgToken.allMatches(d)) m[0]!];
  var i = 0;
  var command = 'M';
  var x = 0.0, y = 0.0, startX = 0.0, startY = 0.0;
  // The second control point of the last curve, for S to mirror.
  double? controlX, controlY;
  double next() => double.parse(t[i++]);
  while (i < t.length) {
    if (_svgCommand(t[i])) command = t[i++];
    final relative = command == command.toLowerCase();
    final dx = relative ? x : 0.0;
    final dy = relative ? y : 0.0;
    var curve = false;
    switch (command.toUpperCase()) {
      case 'Z':
        p.close();
        x = startX;
        y = startY;
        if (i < t.length && !_svgCommand(t[i])) {
          throw FormatException('Numbers after Z', d);
        }
      case 'M':
        x = next() + dx;
        y = next() + dy;
        p.moveTo(x, y);
        startX = x;
        startY = y;
        // Pairs after the first are lines.
        command = relative ? 'l' : 'L';
      case 'L':
        x = next() + dx;
        y = next() + dy;
        p.lineTo(x, y);
      case 'H':
        x = next() + dx;
        p.lineTo(x, y);
      case 'V':
        y = next() + dy;
        p.lineTo(x, y);
      case 'C':
        final x1 = next() + dx, y1 = next() + dy;
        final x2 = next() + dx, y2 = next() + dy;
        x = next() + dx;
        y = next() + dy;
        p.cubicTo(x1, y1, x2, y2, x, y);
        controlX = x2;
        controlY = y2;
        curve = true;
      case 'S':
        final x1 = 2 * x - (controlX ?? x), y1 = 2 * y - (controlY ?? y);
        final x2 = next() + dx, y2 = next() + dy;
        x = next() + dx;
        y = next() + dy;
        p.cubicTo(x1, y1, x2, y2, x, y);
        controlX = x2;
        controlY = y2;
        curve = true;
      case 'A':
        final rx = next(), ry = next(), rotation = next();
        final large = next() != 0, sweep = next() != 0;
        x = next() + dx;
        y = next() + dy;
        p.arcToPoint(
          Offset(x, y),
          radius: Radius.elliptical(rx, ry),
          rotation: rotation,
          largeArc: large,
          clockwise: sweep,
        );
      default:
        throw FormatException('Unknown command $command', d);
    }
    if (!curve) {
      controlX = null;
      controlY = null;
    }
  }
}

